// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, ReentrancyGuard, RosterBtcPutSeries, SafeERC20} from "./RosterBtcPutSeries.sol";
import {RosterSeriesFactory} from "./RosterSeriesFactory.sol";

/// @title Roster Secondary Ask Book
/// @notice Escrowed, partially fillable secondary listings for Roster position tokens.
/// @dev Sellers escrow position lots; buyers pay MUSD directly to the seller minus a
///      protocol fill fee (in basis points) that is forwarded to the feeRecipient.
///      The book supplies a public ask side and therefore observable secondary price
///      discovery. It is intentionally not a matching engine and has no bids or keepers.
///      Listings must be cancelled before maturity because the series freezes transfers.
///
///      A listing is accepted only if the series is registered by the configured factory
///      and its MUSD asset matches the book's MUSD. This prevents a buyer from paying in
///      one MUSD-like token for a position that settles in another.
///
///      Fill fee:
///        buyer pays  = lots × pricePerLot
///        seller gets = lots × pricePerLot × (10_000 - fillFeeBps) / 10_000
///        fee gets    = buyer pays - seller gets
///      The fill fee accrues in this contract and is swept by the feeRecipient.
contract RosterOrderBook is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_FILL_FEE_BPS = 500; // 5% hard cap

    error ZeroAddress();
    error InvalidFactory();
    error InvalidSeries();
    error SeriesNotRegistered();
    error SeriesMismatchedMUSD();
    error InvalidQuantity();
    error InvalidPrice();
    error SeriesNotLive();
    error UnknownListing();
    error ListingNotActive();
    error NotSeller();
    error InsufficientListing();
    error AmountOverflow();
    error InvalidFeeBps();
    error NothingToSweep();

    struct Listing {
        address seller;
        RosterBtcPutSeries series;
        uint256 pricePerLot;
        uint256 remaining;
        bool active;
    }

    IERC20 public immutable musd;
    RosterSeriesFactory public immutable factory;
    /// @notice Protocol fill fee in basis points, taken from the gross fill amount.
    uint256 public immutable fillFeeBps;
    /// @notice Receives accrued fill fees; sweepable by anyone (permissionless flush).
    address public immutable feeRecipient;

    uint256 public nextListingId = 1;
    /// @notice Total protocol fees accrued but not yet swept.
    uint256 public accruedFees;

    mapping(uint256 listingId => Listing listing) public listings;

    event Listed(
        uint256 indexed listingId,
        address indexed seller,
        address indexed series,
        uint256 lots,
        uint256 pricePerLot
    );
    event Filled(
        uint256 indexed listingId,
        address indexed buyer,
        uint256 lots,
        uint256 grossPaid,
        uint256 feeCharged
    );
    event Cancelled(uint256 indexed listingId, uint256 lotsReturned);
    event FeeSwept(address indexed feeRecipient, uint256 amount);

    constructor(
        address musd_,
        address factory_,
        address feeRecipient_,
        uint256 fillFeeBps_
    ) {
        if (
            musd_ == address(0) ||
            factory_ == address(0) ||
            feeRecipient_ == address(0)
        ) revert ZeroAddress();
        if (factory_.code.length == 0) revert InvalidFactory();
        if (RosterSeriesFactory(factory_).musd() != musd_)
            revert InvalidFactory();
        if (fillFeeBps_ > MAX_FILL_FEE_BPS) revert InvalidFeeBps();
        musd = IERC20(musd_);
        factory = RosterSeriesFactory(factory_);
        feeRecipient = feeRecipient_;
        fillFeeBps = fillFeeBps_;
    }

    /// @notice Escrow position lots and publish an ask. Requires prior series approval.
    function list(
        address seriesAddress,
        uint256 lots,
        uint256 pricePerLot
    ) external nonReentrant returns (uint256 listingId) {
        if (seriesAddress == address(0)) revert ZeroAddress();
        if (seriesAddress.code.length == 0) revert InvalidSeries();
        if (lots == 0) revert InvalidQuantity();
        if (pricePerLot == 0) revert InvalidPrice();

        RosterBtcPutSeries series = RosterBtcPutSeries(seriesAddress);

        // The series must settle in this book's MUSD and be a factory-created series.
        // Check the asset first so a mismatched series cannot be mistaken for a typo.
        if (address(series.musd()) != address(musd))
            revert SeriesMismatchedMUSD();
        if (!factory.isSeries(seriesAddress)) revert SeriesNotRegistered();
        if (series.expired() || block.timestamp >= series.expiry())
            revert SeriesNotLive();

        IERC20(address(series)).safeTransferFrom(
            msg.sender,
            address(this),
            lots
        );

        listingId = nextListingId++;
        listings[listingId] = Listing({
            seller: msg.sender,
            series: series,
            pricePerLot: pricePerLot,
            remaining: lots,
            active: true
        });

        emit Listed(listingId, msg.sender, seriesAddress, lots, pricePerLot);
    }

    /// @notice Buy all or part of a listing at the seller's ask.
    /// @dev    Buyer pays the gross amount. The fill fee is deducted before forwarding
    ///         to the seller and held in this contract until swept.
    function fill(uint256 listingId, uint256 lots) external nonReentrant {
        if (lots == 0) revert InvalidQuantity();
        Listing storage listing = listings[listingId];
        if (listing.seller == address(0)) revert UnknownListing();
        if (!listing.active) revert ListingNotActive();
        if (lots > listing.remaining) revert InsufficientListing();
        if (
            listing.series.expired() ||
            block.timestamp >= listing.series.expiry()
        ) {
            revert SeriesNotLive();
        }
        if (lots > type(uint256).max / listing.pricePerLot)
            revert AmountOverflow();

        uint256 grossCost = lots * listing.pricePerLot;
        uint256 feeCharged = fillFeeBps == 0
            ? 0
            : (grossCost * fillFeeBps) / 10_000;
        uint256 sellerProceeds = grossCost - feeCharged;

        listing.remaining -= lots;
        if (listing.remaining == 0) listing.active = false;

        // Pull gross from buyer.
        musd.safeTransferFrom(msg.sender, address(this), grossCost);
        // Forward net to seller immediately.
        musd.safeTransfer(listing.seller, sellerProceeds);
        // Accrue fee for later sweep.
        if (feeCharged != 0) {
            accruedFees += feeCharged;
        }
        IERC20(address(listing.series)).safeTransfer(msg.sender, lots);

        emit Filled(listingId, msg.sender, lots, grossCost, feeCharged);
    }

    /// @notice Return remaining escrowed lots to the seller. Must be called before maturity.
    function cancel(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        if (listing.seller == address(0)) revert UnknownListing();
        if (listing.seller != msg.sender) revert NotSeller();
        if (!listing.active) revert ListingNotActive();
        if (
            listing.series.expired() ||
            block.timestamp >= listing.series.expiry()
        ) {
            revert SeriesNotLive();
        }

        uint256 lotsReturned = listing.remaining;
        listing.remaining = 0;
        listing.active = false;
        IERC20(address(listing.series)).safeTransfer(msg.sender, lotsReturned);

        emit Cancelled(listingId, lotsReturned);
    }

    /// @notice Permissionlessly flush accrued fill fees to feeRecipient.
    function sweepFees() external nonReentrant {
        uint256 amount = accruedFees;
        if (amount == 0) revert NothingToSweep();
        accruedFees = 0;
        musd.safeTransfer(feeRecipient, amount);
        emit FeeSwept(feeRecipient, amount);
    }

    function getListing(
        uint256 listingId
    ) external view returns (Listing memory) {
        return listings[listingId];
    }
}

src/RosterPositionWrapper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, ReentrancyGuard, RosterBtcPutSeries, SafeERC20} from "./RosterBtcPutSeries.sol";

/// @title Roster Position Wrapper
/// @notice Standard 18-decimal ERC-20 wrapper for one Roster series position.
/// @dev One wrapper unit of 1e18 represents one 1e-6 BTC lot. The wrapper custodies the
///      underlying series positions and gives external protocols a conventional ERC-20
///      plus a single-call exercise path. It does not change the series' settlement terms,
///      create leverage, or make the position redeemable for collateral. The underlying
///      series freezes transfers at expiry, so wrapper tokens have no value after expiry.
contract RosterPositionWrapper is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant UNIT = 1e18;

    error ZeroAddress();
    error InvalidSeries();
    error InvalidQuantity();
    error InvalidRecipient();
    error InvalidSender();
    error NotLive();
    error InsufficientBalance();
    error InsufficientAllowance();
    error UnexpectedTokenAmount(address token);

    RosterBtcPutSeries public immutable series;
    IERC20 public immutable musd;
    IERC20 public immutable btc;

    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address account => uint256 amount) public balanceOf;
    mapping(address owner => mapping(address spender => uint256 amount)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Deposited(address indexed account, uint256 lots, uint256 wrapperAmount);
    event Withdrawn(address indexed account, uint256 lots, uint256 wrapperAmount);
    event Exercised(address indexed account, uint256 lots, uint256 btcAmount, uint256 musdPayout);

    constructor(RosterBtcPutSeries series_, string memory name_, string memory symbol_) {
        if (address(series_) == address(0)) revert ZeroAddress();
        if (address(series_).code.length == 0) revert InvalidSeries();
        series = series_;
        musd = IERC20(address(series_.musd()));
        btc = IERC20(address(series_.btc()));
        name = name_;
        symbol = symbol_;
    }

    /// @notice Wrap `lots` underlying position tokens. Requires prior series approval.
    function deposit(uint256 lots) external nonReentrant {
        if (lots == 0) revert InvalidQuantity();
        _requireLive();

        uint256 wrapperAmount = lots * UNIT;
        uint256 beforeBalance = series.balanceOf(address(this));
        if (!series.transferFrom(msg.sender, address(this), lots)) revert UnexpectedTokenAmount(address(series));
        if (series.balanceOf(address(this)) - beforeBalance != lots) revert UnexpectedTokenAmount(address(series));

        _mint(msg.sender, wrapperAmount);
        emit Deposited(msg.sender, lots, wrapperAmount);
    }

    /// @notice Unwrap `wrapperAmount` and receive the underlying position lots.
    function withdraw(uint256 wrapperAmount) external nonReentrant {
        _requireLotMultiple(wrapperAmount);
        _requireLive();

        uint256 lots = wrapperAmount / UNIT;
        _burn(msg.sender, wrapperAmount);
        if (!series.transfer(msg.sender, lots)) revert UnexpectedTokenAmount(address(series));
        emit Withdrawn(msg.sender, lots, wrapperAmount);
    }

    /// @notice Exercise wrapped positions. The caller supplies and approves ERC-20 BTC.
    ///         The series sends the BTC to its writer and the MUSD payout to this wrapper,
    ///         which forwards the payout to the caller.
    function exercise(uint256 wrapperAmount) external nonReentrant {
        _requireLotMultiple(wrapperAmount);
        _requireLive();

        uint256 lots = wrapperAmount / UNIT;
        uint256 btcAmount = lots * series.LOT_SIZE_RAW();
        uint256 musdPayout = lots * series.strike_per_lot_raw();

        _burn(msg.sender, wrapperAmount);

        uint256 btcBefore = btc.balanceOf(address(this));
        btc.safeTransferFrom(msg.sender, address(this), btcAmount);
        _requireExactIncrease(btc, address(this), btcBefore, btcAmount);

        if (btc.allowance(address(this), address(series)) != 0) {
            btc.safeApprove(address(series), 0);
        }
        btc.safeApprove(address(series), btcAmount);

        uint256 musdBefore = musd.balanceOf(address(this));
        series.exercise(lots);
        uint256 received = musd.balanceOf(address(this)) - musdBefore;
        if (received != musdPayout) revert UnexpectedTokenAmount(address(musd));

        btc.safeApprove(address(series), 0);
        musd.safeTransfer(msg.sender, received);
        emit Exercised(msg.sender, lots, btcAmount, received);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        if (spender == address(0)) revert InvalidRecipient();
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external nonReentrant returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external nonReentrant returns (bool) {
        uint256 currentAllowance = allowance[from][msg.sender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < value) revert InsufficientAllowance();
            unchecked {
                allowance[from][msg.sender] = currentAllowance - value;
            }
            emit Approval(from, msg.sender, allowance[from][msg.sender]);
        }
        _transfer(from, to, value);
        return true;
    }

    /// @notice Underlying position lots held by this wrapper.
    function underlyingLots() external view returns (uint256) {
        return series.balanceOf(address(this));
    }

    /// @notice True while deposit, withdraw, and exercise are available.
    function isLive() public view returns (bool) {
        return !series.expired() && block.timestamp < series.expiry();
    }

    function _requireLive() private view {
        if (!isLive()) revert NotLive();
    }

    function _requireLotMultiple(uint256 wrapperAmount) private pure {
        if (wrapperAmount == 0 || wrapperAmount % UNIT != 0) revert InvalidQuantity();
    }

    function _transfer(address from, address to, uint256 value) private {
        if (from == address(0)) revert InvalidSender();
        if (to == address(0)) revert InvalidRecipient();
        uint256 fromBalance = balanceOf[from];
        if (fromBalance < value) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = fromBalance - value;
            balanceOf[to] += value;
        }
        emit Transfer(from, to, value);
    }

    function _mint(address to, uint256 value) private {
        if (to == address(0)) revert InvalidRecipient();
        totalSupply += value;
        balanceOf[to] += value;
        emit Transfer(address(0), to, value);
    }

    function _burn(address from, uint256 value) private {
        uint256 fromBalance = balanceOf[from];
        if (fromBalance < value) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = fromBalance - value;
            totalSupply -= value;
        }
        emit Transfer(from, address(0), value);
    }

    function _requireExactIncrease(IERC20 token, address account, uint256 beforeBalance, uint256 amount) private view {
        uint256 afterBalance = token.balanceOf(account);
        if (afterBalance < beforeBalance || afterBalance - beforeBalance != amount) {
            revert UnexpectedTokenAmount(address(token));
        }
    }
}

src/RosterSeriesFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {RosterBtcPutSeries} from "./RosterBtcPutSeries.sol";

/// @title Roster Series Factory
/// @notice Permissionless registry for fixed-series BTC puts on Mezo.
/// @dev The factory fixes the MUSD, BTC, and fee-recipient assets. Writers compete on
///      strike, premium, expiry, and branding by deploying independent, immutable series.
///      A factory deployment does not prove that a series is funded or demand exists.
///      All series created through this factory share the same feeRecipient and feeBps
///      set at construction. Zero feeBps is valid (fee-free mode for testnet).
contract RosterSeriesFactory {
    error ZeroAddress();
    error IdenticalTokenAddresses();
    error InvalidFeeBps();

    address public immutable musd;
    address public immutable btc;
    /// @notice Protocol fee basis points applied to every series created through this factory.
    uint256 public immutable feeBps;
    /// @notice Receives the per-purchase protocol fee from every series created here.
    address public immutable feeRecipient;

    address[] private _series;
    mapping(address series => bool known) public isSeries;

    event SeriesCreated(
        address indexed series,
        address indexed writer,
        uint256 strikeRaw,
        uint256 premiumPerLotRaw,
        uint256 expiry,
        string name,
        string symbol
    );

    constructor(
        address musd_,
        address btc_,
        address feeRecipient_,
        uint256 feeBps_
    ) {
        if (
            musd_ == address(0) ||
            btc_ == address(0) ||
            feeRecipient_ == address(0)
        ) revert ZeroAddress();
        if (musd_ == btc_) revert IdenticalTokenAddresses();
        if (feeBps_ > 500) revert InvalidFeeBps(); // 5% hard cap, matches RosterBtcPutSeries.MAX_FEE_BPS
        musd = musd_;
        btc = btc_;
        feeRecipient = feeRecipient_;
        feeBps = feeBps_;
    }

    /// @notice Deploy a new immutable series. Anyone may create one; the named writer
    ///         must separately approve and deposit MUSD before buyers can purchase.
    function createSeries(
        address writer,
        uint256 K_raw,
        uint256 premiumPerLot_raw,
        uint256 expiry,
        string calldata name,
        string calldata symbol
    ) external returns (RosterBtcPutSeries series) {
        series = new RosterBtcPutSeries(
            writer,
            musd,
            btc,
            K_raw,
            premiumPerLot_raw,
            expiry,
            name,
            symbol,
            feeRecipient,
            feeBps
        );
        address seriesAddress = address(series);
        _series.push(seriesAddress);
        isSeries[seriesAddress] = true;
        emit SeriesCreated(
            seriesAddress,
            writer,
            K_raw,
            premiumPerLot_raw,
            expiry,
            name,
            symbol
        );
    }

    function seriesCount() external view returns (uint256) {
        return _series.length;
    }

    function seriesAt(uint256 index) external view returns (address) {
        return _series[index];
    }

    function allSeries() external view returns (address[] memory) {
        return _series;
    }
}

src/RosterTroveWriter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, ReentrancyGuard, RosterBtcPutSeries, SafeERC20} from "./RosterBtcPutSeries.sol";

interface IBorrowerOperations {
    function openTrove(
        uint256 debtAmount,
        address upperHint,
        address lowerHint
    ) external payable;
    function addColl(address upperHint, address lowerHint) external payable;
    function withdrawColl(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external;
    function withdrawMUSD(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external;
    function repayMUSD(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external;
    function closeTrove() external;
    function claimCollateral() external;
    function activePool() external view returns (address);
    function collSurplusPool() external view returns (address);
    function MUSD_GAS_COMPENSATION() external view returns (uint256);
}

interface ITroveManager {
    function updateSystemAndTroveInterest(address borrower) external;
    function getTroveStatus(address borrower) external view returns (uint8);
    function getTroveDebt(address borrower) external view returns (uint256);
    function getTroveColl(address borrower) external view returns (uint256);
    function getCurrentICR(
        address borrower,
        uint256 price
    ) external view returns (uint256);
    /// @dev Returns the Total Collateral Ratio of the system (sum of all trove collateral
    ///      over total MUSD supply). Mezo enters Recovery Mode when TCR < CCR (150%).
    function getTCR(uint256 price) external view returns (uint256);
    /// @dev True when the system is in Recovery Mode (TCR < CCR).
    function checkRecoveryMode(uint256 price) external view returns (bool);
}

interface IMezoPriceFeed {
    function fetchPrice() external view returns (uint256);
}

/// @title Roster Trove Writer
/// @notice A separate, per-series vault bound to one factory-created Roster series.
///         It opens a Mezo trove with native BTC, borrows MUSD, and deposits that MUSD
///         into the series as writer collateral.
/// @dev Native BTC trove collateral and the series' ERC-20 BTC underlying are separate
///      assets. This vault never converts one into the other. Trove debt, interest, and
///      liquidation risk belong to the owner. The series reserve is a separate bucket and
///      remains fully collateralized even if the trove is liquidated. Exercised ERC-20 BTC
///      is held for the owner and withdrawn explicitly with withdrawBtc().
contract RosterTroveWriter is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 private constant TROVE_STATUS_ACTIVE = 1;
    uint256 private constant MIN_ALLOWED_ICR = 1.2e18;
    uint256 private constant MAX_ALLOWED_ICR = 5e18;

    error ZeroAddress();
    error NotAContract();
    error OnlyOwner();
    error SeriesNotBound();
    error SeriesAlreadyBound();
    error InvalidSeries();
    error TroveAlreadyOpen();
    error TroveNotActive(uint8 status);
    error NoCollateral();
    error InvalidDeposit();
    error InvalidMinICR();
    error ICRTooLow(uint256 icr);
    error InsufficientMUSD();
    error InsufficientIdleMUSD(uint256 requested, uint256 available);
    error NoPremium();
    error NothingToWithdraw();
    error NativeTransferFailed();
    error UnexpectedNativeAmount();
    error UnexpectedNativeSender();
    error NoDebt();
    /// @notice Reverts when Mezo is in Recovery Mode and the operation would increase
    ///         system indebtedness. The writer is long BTC through the trove and must
    ///         not worsen the system's collateral ratio during stressed conditions.
    error RecoveryModeActive(uint256 tcr);

    address public owner;
    IBorrowerOperations public immutable borrowerOperations;
    ITroveManager public immutable troveManager;
    IMezoPriceFeed public immutable priceFeed;
    IERC20 public immutable musd;
    IERC20 public immutable btc;
    address public immutable activePool;
    address public immutable collSurplusPool;
    uint256 public immutable musdGasCompensation;

    RosterBtcPutSeries public series;
    bool public seriesBound;

    /// @notice Application-level minimum ICR. Always strictly above Mezo's 110% MCR.
    uint256 public minICR;
    uint256 public totalDepositedToSeries;
    uint256 public premiumForwarded;
    uint256 public expiryForwarded;

    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );
    event MinICRUpdated(uint256 minICR);
    event SeriesBound(address indexed series);
    event TroveOpened(uint256 collateral, uint256 debt, uint256 seriesDeposit);
    event CollateralAdded(uint256 amount);
    event CollateralWithdrawn(uint256 amount);
    event MUSDWithdrawnFromTrove(uint256 amount);
    event SeriesFunded(uint256 amount);
    event DebtRepaid(uint256 amount);
    event PremiumForwarded(uint256 amount);
    event ExpiryReleaseForwarded(uint256 amount);
    event TroveClosed(uint256 collateralReturned);
    event CollateralSurplusClaimed(uint256 amount);
    event BtcWithdrawn(address indexed to, uint256 amount);
    event IdleMUSDWithdrawn(uint256 amount);
    event RecoveryModeBlocked(uint256 tcr);

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    constructor(
        address owner_,
        address borrowerOperations_,
        address troveManager_,
        address priceFeed_,
        address musd_,
        address btc_,
        uint256 minICR_
    ) {
        if (
            owner_ == address(0) ||
            borrowerOperations_ == address(0) ||
            troveManager_ == address(0) ||
            priceFeed_ == address(0) ||
            musd_ == address(0) ||
            btc_ == address(0)
        ) revert ZeroAddress();
        if (
            borrowerOperations_.code.length == 0 ||
            troveManager_.code.length == 0 ||
            priceFeed_.code.length == 0
        ) {
            revert NotAContract();
        }
        if (minICR_ < MIN_ALLOWED_ICR || minICR_ > MAX_ALLOWED_ICR)
            revert InvalidMinICR();

        address activePool_ = IBorrowerOperations(borrowerOperations_)
            .activePool();
        address collSurplusPool_ = IBorrowerOperations(borrowerOperations_)
            .collSurplusPool();
        if (activePool_ == address(0) || collSurplusPool_ == address(0))
            revert ZeroAddress();
        if (activePool_.code.length == 0 || collSurplusPool_.code.length == 0)
            revert NotAContract();

        owner = owner_;
        borrowerOperations = IBorrowerOperations(borrowerOperations_);
        troveManager = ITroveManager(troveManager_);
        priceFeed = IMezoPriceFeed(priceFeed_);
        musd = IERC20(musd_);
        btc = IERC20(btc_);
        activePool = activePool_;
        collSurplusPool = collSurplusPool_;
        musdGasCompensation = IBorrowerOperations(borrowerOperations_)
            .MUSD_GAS_COMPENSATION();
        minICR = minICR_;
    }

    /// @dev Mezo returns collateral from ActivePool (closure/withdrawal) and
    ///      CollSurplusPool (surplus recovery), not from BorrowerOperations itself.
    ///      Accept exactly those two resolved pool addresses; reject every other sender.
    receive() external payable {
        if (msg.sender != activePool && msg.sender != collSurplusPool) {
            revert UnexpectedNativeSender();
        }
    }

    /// @notice Bind this vault to its factory-created series once. The series must name
    ///         this vault as writer and use the same MUSD and BTC assets.
    function bindSeries(address seriesAddress) external onlyOwner {
        if (seriesBound) revert SeriesAlreadyBound();
        if (seriesAddress == address(0) || seriesAddress.code.length == 0)
            revert InvalidSeries();
        RosterBtcPutSeries candidate = RosterBtcPutSeries(seriesAddress);
        if (candidate.writer() != address(this)) revert InvalidSeries();
        if (address(candidate.musd()) != address(musd)) revert InvalidSeries();
        if (address(candidate.btc()) != address(btc)) revert InvalidSeries();
        series = candidate;
        seriesBound = true;
        emit SeriesBound(seriesAddress);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function setMinICR(uint256 newMinICR) external onlyOwner {
        if (newMinICR < MIN_ALLOWED_ICR || newMinICR > MAX_ALLOWED_ICR)
            revert InvalidMinICR();
        minICR = newMinICR;
        emit MinICRUpdated(newMinICR);
    }

    /// @notice Open a Mezo trove with native BTC, borrow MUSD, and deposit part of it
    ///         into this vault's series. Interest and debt remain the owner's obligation.
    function openAndFund(
        uint256 debtAmount,
        uint256 seriesDeposit,
        address upperHint,
        address lowerHint
    ) external payable onlyOwner nonReentrant {
        _requireSeriesBound();
        if (troveManager.getTroveStatus(address(this)) == TROVE_STATUS_ACTIVE) {
            revert TroveAlreadyOpen();
        }
        if (msg.value == 0) revert NoCollateral();
        if (seriesDeposit == 0 || seriesDeposit > debtAmount)
            revert InvalidDeposit();

        // Opening a trove increases system debt. Block during Recovery Mode so the
        // vault cannot worsen a system-level collateral crisis.
        _requireNotRecoveryMode();

        borrowerOperations.openTrove{value: msg.value}(
            debtAmount,
            upperHint,
            lowerHint
        );

        if (musd.balanceOf(address(this)) < seriesDeposit)
            revert InsufficientMUSD();
        _fundSeries(seriesDeposit);
        _checkICR();
        emit TroveOpened(msg.value, debtAmount, seriesDeposit);
    }

    function addCollateral(
        address upperHint,
        address lowerHint
    ) external payable onlyOwner nonReentrant {
        _requireActiveTrove();
        if (msg.value == 0) revert NoCollateral();
        borrowerOperations.addColl{value: msg.value}(upperHint, lowerHint);
        emit CollateralAdded(msg.value);
    }

    function withdrawCollateral(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external onlyOwner nonReentrant {
        _requireActiveTrove();
        if (amount == 0) revert NothingToWithdraw();
        uint256 before = address(this).balance;
        borrowerOperations.withdrawColl(amount, upperHint, lowerHint);
        uint256 received = address(this).balance - before;
        if (received != amount) revert UnexpectedNativeAmount();
        _checkICR();
        _sendNative(owner, received);
        emit CollateralWithdrawn(amount);
    }

    function borrowMore(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external onlyOwner nonReentrant {
        _requireActiveTrove();
        if (amount == 0) revert NothingToWithdraw();
        // Borrowing more increases system debt. Block during Recovery Mode.
        _requireNotRecoveryMode();
        borrowerOperations.withdrawMUSD(amount, upperHint, lowerHint);
        _checkICR();
        emit MUSDWithdrawnFromTrove(amount);
    }

    /// @notice Move idle borrowed MUSD into the series as additional writer collateral.
    function depositToSeries(uint256 amount) external onlyOwner nonReentrant {
        _requireSeriesBound();
        if (amount == 0) revert InvalidDeposit();
        uint256 available = idleMUSD();
        if (amount > available) revert InsufficientIdleMUSD(amount, available);
        _fundSeries(amount);
    }

    /// @notice Partial repayment. Mezo burns MUSD directly from this vault.
    function repay(
        uint256 amount,
        address upperHint,
        address lowerHint
    ) external onlyOwner nonReentrant {
        _requireActiveTrove();
        if (amount == 0) revert NothingToWithdraw();
        musd.safeTransferFrom(msg.sender, address(this), amount);
        borrowerOperations.repayMUSD(amount, upperHint, lowerHint);
        emit DebtRepaid(amount);
    }

    /// @notice Full closure. Mezo burns the remaining debt minus gas compensation from
    ///         this vault and returns native BTC collateral. Pulls only the MUSD shortfall
    ///         from the owner and preserves any unforwarded series expiry release.
    function closeTrove() external onlyOwner nonReentrant {
        _requireActiveTrove();
        troveManager.updateSystemAndTroveInterest(address(this));
        uint256 debt = troveManager.getTroveDebt(address(this));
        if (debt <= musdGasCompensation) revert NoDebt();
        uint256 required = debt - musdGasCompensation;

        uint256 balance = musd.balanceOf(address(this));
        uint256 reserved = _reservedSeriesProceeds();
        uint256 idle = balance > reserved ? balance - reserved : 0;
        if (idle < required) {
            musd.safeTransferFrom(owner, address(this), required - idle);
        }

        uint256 before = address(this).balance;
        borrowerOperations.closeTrove();
        uint256 received = address(this).balance - before;
        _sendNative(owner, received);
        emit TroveClosed(received);
    }

    /// @notice Recover collateral surplus after a redemption or liquidation.
    function claimCollateral()
        external
        onlyOwner
        nonReentrant
        returns (uint256 received)
    {
        uint256 before = address(this).balance;
        borrowerOperations.claimCollateral();
        received = address(this).balance - before;
        if (received == 0) revert NothingToWithdraw();
        _sendNative(owner, received);
        emit CollateralSurplusClaimed(received);
    }

    /// @notice Withdraw premium earned by the series and forward it to the owner.
    function withdrawPremium()
        external
        onlyOwner
        nonReentrant
        returns (uint256 amount)
    {
        _requireSeriesBound();
        amount = series.premium_balance_raw();
        if (amount == 0) revert NoPremium();
        series.withdrawPremium();
        premiumForwarded += amount;
        musd.safeTransfer(owner, amount);
        emit PremiumForwarded(amount);
    }

    /// @notice Finalize an expired series. Tracks releases so collateral already sent by
    ///         a third-party expire() call is still forwarded exactly once.
    function finalize()
        external
        onlyOwner
        nonReentrant
        returns (uint256 expiryRelease, uint256 premium)
    {
        _requireSeriesBound();
        series.expire();

        uint256 release = series.expiry_release_raw();
        if (release > expiryForwarded) {
            expiryRelease = release - expiryForwarded;
            expiryForwarded = release;
            musd.safeTransfer(owner, expiryRelease);
            emit ExpiryReleaseForwarded(expiryRelease);
        }

        premium = series.premium_balance_raw();
        if (premium != 0) {
            series.withdrawPremium();
            premiumForwarded += premium;
            musd.safeTransfer(owner, premium);
            emit PremiumForwarded(premium);
        }
    }

    /// @notice Withdraw ERC-20 BTC received from physical exercise. Native trove BTC is
    ///         separate and leaves through withdrawCollateral() or closeTrove().
    function withdrawBtc(
        address to,
        uint256 amount
    ) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert NothingToWithdraw();
        btc.safeTransfer(to, amount);
        emit BtcWithdrawn(to, amount);
    }

    /// @notice Withdraw MUSD that is not reserved for an already-released series expiry.
    function withdrawIdleMUSD(uint256 amount) external onlyOwner nonReentrant {
        if (amount == 0) revert NothingToWithdraw();
        uint256 available = idleMUSD();
        if (amount > available) revert InsufficientIdleMUSD(amount, available);
        musd.safeTransfer(owner, amount);
        emit IdleMUSDWithdrawn(amount);
    }

    function isTroveActive() public view returns (bool) {
        return
            troveManager.getTroveStatus(address(this)) == TROVE_STATUS_ACTIVE;
    }

    /// @notice MUSD held by the vault that is not reserved for series expiry collateral.
    function idleMUSD() public view returns (uint256) {
        uint256 balance = musd.balanceOf(address(this));
        uint256 reserved = _reservedSeriesProceeds();
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Series expiry MUSD already received but not yet forwarded to the owner.
    function reservedMUSD() external view returns (uint256) {
        return _reservedSeriesProceeds();
    }

    function troveInfo()
        external
        view
        returns (
            uint256 collateral,
            uint256 debt,
            uint256 icr,
            uint256 price,
            uint8 status
        )
    {
        price = priceFeed.fetchPrice();
        collateral = troveManager.getTroveColl(address(this));
        debt = troveManager.getTroveDebt(address(this));
        status = troveManager.getTroveStatus(address(this));
        icr = debt == 0
            ? type(uint256).max
            : troveManager.getCurrentICR(address(this), price);
    }

    function seriesState()
        external
        view
        returns (
            uint256 collateral,
            uint256 premium,
            uint256 activeLots,
            bool expired
        )
    {
        if (!seriesBound) {
            return (0, 0, 0, false);
        }
        collateral = series.collateral_balance_raw();
        premium = series.premium_balance_raw();
        activeLots = series.active_lots();
        expired = series.expired();
    }

    /// @notice Current system Total Collateral Ratio. Falls below 1.5e18 in Recovery Mode.
    function systemTCR() external view returns (uint256) {
        return troveManager.getTCR(priceFeed.fetchPrice());
    }

    /// @notice True when the Mezo system is in Recovery Mode (TCR < 150%).
    ///         During Recovery Mode, openAndFund and borrowMore are blocked.
    function isInRecoveryMode() external view returns (bool) {
        return troveManager.checkRecoveryMode(priceFeed.fetchPrice());
    }

    function _requireSeriesBound() private view {
        if (!seriesBound) revert SeriesNotBound();
    }

    function _requireActiveTrove() private view {
        uint8 status = troveManager.getTroveStatus(address(this));
        if (status != TROVE_STATUS_ACTIVE) revert TroveNotActive(status);
    }

    function _checkICR() private view {
        uint256 icr = troveManager.getCurrentICR(
            address(this),
            priceFeed.fetchPrice()
        );
        if (icr < minICR) revert ICRTooLow(icr);
    }

    /// @dev Reverts with RecoveryModeActive when the system TCR is below Mezo's CCR.
    ///      This protects the protocol by blocking new debt that would deepen a system crisis.
    ///      Repayments, collateral additions, and closures are explicitly allowed during
    ///      Recovery Mode — they all improve or preserve the system TCR.
    function _requireNotRecoveryMode() private view {
        uint256 price = priceFeed.fetchPrice();
        bool inRecoveryMode = troveManager.checkRecoveryMode(price);
        if (inRecoveryMode) {
            uint256 tcr = troveManager.getTCR(price);
            revert RecoveryModeActive(tcr);
        }
    }

    function _reservedSeriesProceeds() private view returns (uint256) {
        if (!seriesBound) return 0;
        uint256 release = series.expiry_release_raw();
        return release > expiryForwarded ? release - expiryForwarded : 0;
    }

    function _fundSeries(uint256 amount) private {
        musd.safeApprove(address(series), amount);
        series.deposit(amount);
        totalDepositedToSeries += amount;
        emit SeriesFunded(amount);
    }

    function _sendNative(address to, uint256 amount) private {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert NativeTransferFailed();
    }
}

